async function loadPhoto(file){const ticket=++photoTicket;if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){notify('请上传 JPEG、PNG 或 WebP；NEF 可先用尼康软件导出 JPEG',true);return;}if(file.size>50*1024*1024){notify('照片超过 50 MB，请先缩小文件',true);return;}try{const bitmap=await createImageBitmap(file);if(ticket!==photoTicket){bitmap.close();return;}const scale=Math.min(1,1280/bitmap.width,1000/bitmap.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);loadCanvas(canvas,file.name,bitmap.width,bitmap.height);bitmap.close();notify('照片已在本机加载');}catch{notify('无法读取这张照片，请换用标准 JPEG、PNG 或 WebP',true);}}
$('photoFile').onchange=e=>{loadPhoto(e.target.files[0]);e.target.value='';};
