function drawHistogram(){if(!source||!lastPreview)return;const canvas=$('histogram'),ctx=canvas.getContext('2d'),hist=data=>{const bins=new Uint32Array(128);for(let i=0;i<data.length;i+=32)bins[Math.min(127,Math.floor((data[i]*.2126+data[i+1]*.7152+data[i+2]*.0722)/2))]++;return bins;};const a=hist(source.pixels),b=hist(lastPreview),max=Math.max(1,...a,...b);ctx.clearRect(0,0,canvas.width,canvas.height);for(const[bins,color]of [[a,'#67717a88'],[b,'#e8cd54c0']]){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,canvas.height);for(let i=0;i<128;i++)ctx.lineTo(i*canvas.width/127,canvas.height-4-Math.sqrt(bins[i]/max)*(canvas.height-8));ctx.lineTo(canvas.width,canvas.height);ctx.closePath();ctx.fill();}}
