function updateFilename(){const slot=Number($('cameraSlot').value);$('filePreview').textContent=Number.isInteger(slot)&&slot>=1&&slot<=99?`PICCON${String(slot).padStart(2,'0')}.NP3`:'请输入有效文件编号';}
$('cameraSlot').oninput=updateFilename;
function exportSettings(){const next=normalize({...settings,name:$('cameraName').value,slot:Number($('cameraSlot').value)});settings=next;persist();return next;}
function download(data,type,filename){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportAction(kind){try{const s=exportSettings(),safe=s.name.trim().replace(/[^A-Za-z0-9_-]/g,'_');if(kind==='np3')download(encodeNP3(s),'application/octet-stream',cameraFilename(s));else if(kind==='zip')download(makeCardZip(s),'application/zip',`Z50-${safe}-SD.zip`);else download(JSON.stringify({schema:1,camera:'Nikon Z50',fileVersion:'0300',settings:s},null,2),'application/json',`Z50-${safe}.json`);notify(kind==='json'?'可编辑配置已生成':'相机预设已生成，请按说明复制到 SD 卡');}catch(e){notify(e.message,true);}}
$('np3Download').onclick=()=>exportAction('np3');$('zipDownload').onclick=()=>exportAction('zip');$('jsonDownload').onclick=()=>exportAction('json');
$('previewDownload').onclick=()=>{if(busy||!lastPreview){notify('请等待当前预览完成');return;}$('processedCanvas').toBlob(blob=>{if(blob)download(blob,'image/jpeg',`Z50-preview-${source.width}x${source.height}.jpg`);},'image/jpeg',.94);};
$('savePreset').onclick=()=>{$('saveName').value=settings.name;$('saveDialog').showModal();$('saveName').focus();};
$('confirmSave').onclick=()=>{try{const next=normalize({...settings,name:$('saveName').value});const entry={name:next.name,settings:next};saved=[entry,...saved.filter(x=>x.name!==entry.name)].slice(0,30);localStorage.setItem(SAVED,JSON.stringify(saved));settings=next;recipeTitle=next.name;activeStarter=null;persist();showSaved();syncControls();$('saveDialog').close();notify('预设已保存到当前浏览器');}catch(e){notify(e.message,true);}};
$('importButton').onclick=()=>$('recipeFile').click();$('recipeFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>1024*1024){notify('预设文件过大，未加载',true);return;}try{let next;if(/\.np3$/i.test(file.name)){next=decodeNP3(new Uint8Array(await file.arrayBuffer()));const match=file.name.match(/^PICCON(\d{2})\.NP3$/i);if(match&&Number(match[1])>=1)next.slot=Number(match[1]);}else if(/\.json$/i.test(file.name)){const recipe=JSON.parse(await file.text());if(recipe.schema!==1||recipe.camera!=='Nikon Z50'||recipe.fileVersion!=='0300')throw new Error('请选择本工具导出的 Z50 配置 JSON');next=normalize(recipe.settings);}else throw new Error('请选择 NP3 或 JSON 文件');updateSettings(next,next.name);notify('预设已加载，可继续调试');}catch(error){notify(error.message||'无法加载预设',true);}};
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
buildStarters();buildControls();showSaved();syncControls();demo();
